# Example for Testing
Currently I've thrown this all into an example handler for testing. It's not comprehensive, but it touches all the bits I've added, so it makes for a good starting point/demo

```python
from typing import Any, Dict, List, Optional

from llama_index.callbacks.base import BaseCallbackHandler
from llama_index.callbacks.schema import CBEventType, EventPayload


class TestingCallbackHandler(BaseCallbackHandler):
    def __init__(self):
        super().__init__(event_starts_to_ignore=[], event_ends_to_ignore=[])

    def _parse_llm_event(
        self, payload: Dict[str, Any], skip_input: bool = False
    ) -> None:
        if (
            EventPayload.PROMPT in payload
            and payload[EventPayload.PROMPT] is not None
            and not skip_input
        ):
            print(
                "--- PROMPT ---\n", str(payload[EventPayload.PROMPT])[:256], "\n-----"
            )
        if (
            EventPayload.MESSAGES in payload
            and payload[EventPayload.MESSAGES] is not None
            and not skip_input
        ):
            print(
                "--- MESSAGES ---\n",
                str(payload[EventPayload.MESSAGES])[:256],
                "\n-----",
            )

        # additional kwargs contain token counts from the response
        if (
            EventPayload.RESPONSE in payload
            and payload[EventPayload.RESPONSE] is not None
        ):
            print(
                "--- RESPONSE ---\n",
                payload[EventPayload.RESPONSE],
                payload[EventPayload.RESPONSE].additional_kwargs,
                "\n-----",
            )
        if (
            EventPayload.COMPLETION in payload
            and payload[EventPayload.COMPLETION] is not None
        ):
            print(
                "--- COMPLETION ---\n",
                payload[EventPayload.COMPLETION],
                payload[EventPayload.COMPLETION].additional_kwargs,
                "\n-----",
            )

        if (
            EventPayload.ADDITIONAL_KWARGS in payload
            and payload[EventPayload.ADDITIONAL_KWARGS]
        ):
            print(
                "--- ADDITIONAL_KWARGS ---\n",
                payload[EventPayload.ADDITIONAL_KWARGS],
                "\n-----",
            )
        if EventPayload.SERIALIZED in payload and payload[EventPayload.SERIALIZED]:
            print(
                "--- SERIALIZED LLM ---\n", payload[EventPayload.SERIALIZED], "\n-----"
            )

    def _parse_function_call_event(self, payload: Dict[str, Any]) -> None:
        if (
            EventPayload.FUNCTION_CALL in payload
            and payload[EventPayload.FUNCTION_CALL]
        ):
            print(
                "--- FUNCTION_CALL ---\n",
                payload[EventPayload.FUNCTION_CALL],
                "\n-----",
            )
        if EventPayload.TOOL in payload and payload[EventPayload.TOOL]:
            print("--- TOOL ---\n", payload[EventPayload.TOOL], "\n-----")
            print(
                "---- FN SCHEMA ----\n",
                payload[EventPayload.TOOL].fn_schema_str,
                "\n-----",
            )
        if (
            EventPayload.FUNCTION_OUTPUT in payload
            and payload[EventPayload.FUNCTION_OUTPUT]
        ):
            print(
                "--- FUNCTION_OUTPUT ---\n",
                payload[EventPayload.FUNCTION_OUTPUT],
                "\n-----",
            )

    def _parse_embedding_event(self, payload: Dict[str, Any]) -> None:
        if EventPayload.EMBEDDINGS in payload and payload[EventPayload.EMBEDDINGS]:
            # print("--- EMBEDDINGS ---\n", payload[EventPayload.EMBEDDINGS], "\n-----")
            pass
        if EventPayload.NODES in payload and payload[EventPayload.NODES]:
            # print("--- NODES ---\n", payload[EventPayload.NODES], "\n-----")
            pass
        if EventPayload.SERIALIZED in payload and payload[EventPayload.SERIALIZED]:
            print(
                "--- SERIALIZED EMBEDDING MODEL ---\n",
                payload[EventPayload.SERIALIZED],
                "\n-----",
            )

    def _parse_templating_event(self, payload: Dict[str, Any]) -> None:
        if EventPayload.TEMPLATE in payload and payload[EventPayload.TEMPLATE]:
            print("--- TEMPLATE ---\n", payload[EventPayload.TEMPLATE], "\n-----")
        if (
            EventPayload.TEMPLATE_VARS in payload
            and payload[EventPayload.TEMPLATE_VARS]
        ):
            print(
                "--- TEMPLATE_VARS ---\n",
                payload[EventPayload.TEMPLATE_VARS],
                "\n-----",
            )
        if (
            EventPayload.SYSTEM_PROMPT in payload
            and payload[EventPayload.SYSTEM_PROMPT]
        ):
            print(
                "--- SYSTEM_PROMPT ---\n",
                payload[EventPayload.SYSTEM_PROMPT],
                "\n-----",
            )
        if (
            EventPayload.QUERY_WRAPPER_PROMPT in payload
            and payload[EventPayload.QUERY_WRAPPER_PROMPT]
        ):
            print(
                "--- QUERY_WRAPPER_PROMPT ---\n",
                payload[EventPayload.QUERY_WRAPPER_PROMPT],
                "\n-----",
            )

    def _parse_reranking_event(self, payload: Dict[str, Any]) -> None:
        if EventPayload.MODEL_NAME in payload and payload[EventPayload.MODEL_NAME]:
            print(
                "--- RERANKING MODEL_NAME ---\n",
                payload[EventPayload.MODEL_NAME],
                "\n-----",
            )
        if EventPayload.NODES in payload and payload[EventPayload.NODES]:
            # print("--- RERANKING NODES ---\n", payload[EventPayload.NODES], "\n-----")
            scores = [n.score for n in payload[EventPayload.NODES]]
            print("--- RERANKING SCORES ---\n", scores, "\n-----")
            pass
        if EventPayload.TOP_K in payload and payload[EventPayload.TOP_K]:
            print("--- RERANKING TOP_K ---\n", payload[EventPayload.TOP_K], "\n-----")

    def _parse_retrieve_event(self, payload: Dict[str, Any]) -> None:
        if EventPayload.QUERY_STR in payload and payload[EventPayload.QUERY_STR]:
            print(
                "--- RETRIEVE QUERY_STR ---\n",
                payload[EventPayload.QUERY_STR],
                "\n-----",
            )
        if EventPayload.NODES in payload and payload[EventPayload.NODES]:
            # print("--- RETRIEVE NODES ---\n", payload[EventPayload.NODES], "\n-----")
            pass

    def _parse_exception_event(self, payload: Dict[str, Any]) -> None:
        if EventPayload.EXCEPTION in payload and payload[EventPayload.EXCEPTION]:
            print("--- EXCEPTION ---\n", payload[EventPayload.EXCEPTION], "\n-----")

    def on_event_start(
        self,
        event_type: CBEventType,
        payload: Optional[EventPayload] = None,
        event_id: str = "",
        **kwargs: Any,
    ) -> str:
        if payload is None:
            return

        if event_type == CBEventType.EXCEPTION:
            self._parse_exception_event(payload)
        elif event_type == CBEventType.LLM:
            self._parse_llm_event(payload)
        elif event_type == CBEventType.FUNCTION_CALL:
            self._parse_function_call_event(payload)
        elif event_type == CBEventType.EMBEDDING:
            self._parse_embedding_event(payload)
        elif event_type == CBEventType.TEMPLATING:
            self._parse_templating_event(payload)
        elif event_type == CBEventType.RERANKING:
            self._parse_reranking_event(payload)
        elif event_type == CBEventType.RETRIEVE:
            self._parse_retrieve_event(payload)

        return event_id

    def on_event_end(
        self,
        event_type: CBEventType,
        payload: Dict[str, Any] | None = None,
        event_id: str = "",
        **kwargs: Any,
    ) -> None:
        if payload is None:
            return

        if event_type == CBEventType.LLM:
            self._parse_llm_event(payload, skip_input=True)
        elif event_type == CBEventType.FUNCTION_CALL:
            self._parse_function_call_event(payload)
        elif event_type == CBEventType.EMBEDDING:
            self._parse_embedding_event(payload)
        elif event_type == CBEventType.TEMPLATING:
            self._parse_templating_event(payload)
        elif event_type == CBEventType.RERANKING:
            self._parse_reranking_event(payload)
        elif event_type == CBEventType.RETRIEVE:
            self._parse_retrieve_event(payload)

    def end_trace(
        self, trace_id: str | None = None, trace_map: Dict[str, List[str]] | None = None
    ) -> None:
        pass

    def start_trace(self, trace_id: str | None = None) -> None:
        pass
```

Furthermore, to test the handler, I have been using this code

```python
from llama_index import VectorStoreIndex, SimpleDirectoryReader, ServiceContext
from llama_index.indices.postprocessor import SentenceTransformerRerank
from llama_index.agent import OpenAIAgent
from llama_index.tools import QueryEngineTool
from llama_index.callbacks import CallbackManager
from llama_index.llms import OpenAI

handler = TestingCallbackHandler()
callback_manager = CallbackManager(handlers=[handler])

llm = OpenAI()

service_context = ServiceContext.from_defaults(
    llm=llm, callback_manager=callback_manager, chunk_size=512
)

documents = SimpleDirectoryReader("./docs/examples/data/paul_graham").load_data()

index = VectorStoreIndex.from_documents(documents, service_context=service_context)

reranker = SentenceTransformerRerank(model="cross-encoder/stsb-distilroberta-base")

query_engine = index.as_query_engine(similarity_top_k=5, node_postprocessors=[reranker])

query_tool = QueryEngineTool.from_defaults(
    query_engine=query_engine,
    name="paul_graham",
    description="Useful for looking up information about Paul Graham's essay.",
)

agent = OpenAIAgent.from_tools([query_tool], llm=llm, callback_manager=callback_manager)

# base agent example
response = agent.query("Hello!")

# too/function call + query engine query + reranker
response = agent.query("What did Paul Graham do growing up?")
```

Thank you LlamaIndex library creators. As a Data Scientist, I have found LlamaIndex to be an incredibly helpful framework for training LLMs on own data.

Recently, while going through the documentation, I came across custom prompts and noticed that the site had been moved from https://gpt-index.readthedocs.io/en/latest/how_to/custom_prompts.html to https://gpt-index.readthedocs.io/en/latest/how_to/customization/custom_prompts.html. I have made a minor edit to rectify it.

@jerryjliu Please let me know if I can improve it? Once again, thank you so much for all your hard work and for making the world of AI model development a better place.

QdrantVectorStore was failing to create new collections with the HTTP client. Reason was that the check for already existing collections did not catch the correct exception from the failing `get_collection` call.

If a collection is not found, Qdrant Client throws an UnexceptedResponse. Added this to checking if collection exists.

@kacperlukawski what do you think of the solution?

The current version can easily and succesfully *query* existing Pinecone namespaces but can't create new ones or delete them. With this change, you can use the same syntax as your query:
```py

insert_kwargs = {
    "pinecone_kwargs": {
        "namespace": namespace,
    }
}

index.insert(document=(Document(text, doc_id=doc_id)), **insert_kwargs)
```

And it will handle your custom namespace:
